const $=id=>document.getElementById(id);
const NAV=[['工作空间',[['overview','home','项目总览'],['graph','graph','本体图谱'],['models','layers','七模型工作台']]],['语义建模',[['flows','flow','流程模型'],['queries','table','查询与报表'],['quality','shield','覆盖与质量'],['ai','spark','AI 分析与确认'],['review','check','校验与评审']]],['项目管理',[['jobs','jobs','建模任务'],['compare','git','快照差异'],['exports','download','版本与导出'],['settings','settings','能力与设置']]]];
const titles=Object.fromEntries(NAV.flatMap(([,items])=>items.map(([id,,label])=>[id,label])));
const S={boot:null,project:null,data:null,route:location.hash.split('/')[1]||'overview',type:'',context:'',search:'',page:1,modelView:'list',graphMode:'all',graphPrefs:{},flowId:'',flowSearch:'',flowLevel:'',reviewTab:'checks',snapshot:null,compare:{},assistantMessages:[],assistantBusy:false};let graph=null,pollTimer=null,loadEpoch=0,sourceEpoch=0;
async function api(path,options={}){const r=await fetch('/api'+path,{...options,headers:{'Content-Type':'application/json',...(options.headers||{})}});const d=await r.json();if(!r.ok)throw Error(d.error||'请求未完成');return d}
const projectAPI=(action='',extra='')=>`/projects/${S.project.id}/${action}${S.snapshot?'?snapshot='+encodeURIComponent(S.snapshot)+(extra?'&'+extra:''):extra?'?'+extra:''}`;
const nodes=()=>S.data?.nodes||[];const reviews=()=>new Map((S.data?.reviews||[]).map(r=>[r.node_id,r]));
function toast(message,error=false){const el=document.createElement('div');el.className='toast'+(error?' error':'');el.innerHTML=icon(error?'info':'check',17)+`<span>${esc(message)}</span>`;$('toast-root').append(el);setTimeout(()=>el.remove(),4500)}
function navigate(route){if(route===S.route){render();return}location.hash='/'+route}
function heading(title,sub,actions=''){return `<div class="page-heading"><div><div class="eyebrow">ONTOLOGY STUDIO / ${esc(S.project?.name||'WORKSPACE')}</div><h1>${title}</h1><p>${sub}</p></div><div class="heading-actions">${actions}</div></div>`}
function mainActions(){return `${S.data?`<button class="button" data-reanalyze>${icon('refresh',14)}重新分析</button>`:''}<button class="button primary" data-new>${icon('plus',15)}接入建模资料</button><button class="button" data-new-docs>${icon('file',15)}知识目录建模</button>`}
function needData(){if(S.data)return false;const active=S.boot?.jobs.find(j=>j.project_id===S.project?.id&&['running','queued'].includes(j.status));$('content').innerHTML=heading('开始构建你的业务语义空间','接入建模资料，让对象、行为与流程逐步变得清晰。',mainActions())+empty(active?'建模任务正在进行':'还没有可查看的本体快照',active?'平台正在提取输入资料中的业务语义。可以前往任务中心查看阶段与日志。':'选择本地代码、HTTPS Git 仓库或知识文档目录开始建模。',active?'<button class="button primary" data-route="jobs">查看建模任务</button>':'<button class="button primary" data-reanalyze>开始分析此项目</button>');return true}
function modelCounts(){return Object.fromEntries(Object.keys(MODEL).map(k=>[k,nodes().filter(n=>n.model===k).length]))}
function activeSnapshot(){return S.project?.latest}
function renderNav(){$('navigation').innerHTML=NAV.map(([group,items])=>`<div class="nav-section">${group}</div>${items.map(([id,ic,label])=>`<a class="nav-link ${S.route===id?'active':''}" href="#/${id}">${icon(ic,16)}<span>${label}</span>${id==='jobs'&&S.boot?.jobs.some(j=>['running','queued'].includes(j.status))?'<span class="nav-count">'+S.boot.jobs.filter(j=>['running','queued'].includes(j.status)).length+'</span>':''}</a>`).join('')}`).join('');$('breadcrumb-current').textContent=titles[S.route]||'项目总览';$('project-title').textContent=S.project?.name||'选择代码项目';$('project-subtitle').textContent=S.project?.source_type==='documents'?'知识文档目录':S.project?.source_type==='git'?'HTTPS Git 仓库':'本地代码仓库';document.querySelector('.project-switch .project-avatar').textContent=(S.project?.name||'O').slice(0,1);$('engine-title').textContent=S.boot?.jobs.some(j=>j.status==='running')?'分析引擎运行中':'本地分析引擎';}
function render(){graph?.destroy();graph=null;renderNav();const fn={overview:renderOverview,graph:renderGraph,models:renderModels,flows:renderFlows,queries:renderQueries,quality:renderQuality,compare:renderCompare,review:renderReview,jobs:renderJobs,exports:renderExports,settings:renderSettings,ai:renderAI}[S.route]||renderOverview;fn();bindContent()}
function renderOverview(){
 if(!S.project){$('content').innerHTML=heading('从资料，读懂业务。','建立统一的业务语义，让每一次技术理解都有据可循。',mainActions())+empty('你的第一个本体项目','从一个代码仓库开始，构建对象、行为、规则与流程之间的关系。','<button class="button primary" data-new>接入建模资料</button>');return}
 if(needData())return;const d=S.data,c=d.counts,checks=d.manifest.validation||[],passed=checks.filter(c=>c.passed).length,counts=modelCounts(),snap=d.snapshot,commit=S.project.source_type==='documents'?d.manifest.source_fingerprint?.slice(0,8)||'AI草稿':snap.commit&&snap.commit!=='unavailable'?snap.commit.slice(0,8):'未记录';const metrics=[['M1',c.objects,'业务对象','聚合与实体的统一描述'],['M2',c.behaviors,'业务行为','从操作入口追溯实现'],['M6',counts.M6,'流程模型',S.project.source_type==='documents'?'文档流程描述 · 待形式化':`${c.lifecycleFlows||0} 条跨端点生命周期`],['M7',counts.M7,'查询契约','参数、返回结构与数据来源']];
 $('content').innerHTML=heading('从资料，读懂业务。','以源码或文档为起点，连接业务知识，构建可追溯、可评审的七模型本体。',mainActions())+
 qualityNotice(d)+(d.manifest.adapter==='document-directory'?documentSummary(d):'')+`<section class="hero"><div class="hero-content"><div class="hero-kicker">KNOWLEDGE TO ONTOLOGY</div><h2>连接代码与文档，读懂业务逻辑</h2><p>从业务对象到端到端流程，将分散的实现连接成清晰的语义图谱。模型元素关联来源证据，并保留需要进一步确认的语义。</p><div class="hero-actions"><button class="button primary" data-route="graph">探索本体图谱 ${icon('arrow',14)}</button><button class="text-button" data-route="models">查看七模型 ${icon('chevron',13)}</button></div></div>${heroGraph()}</section>`+
 `<div class="stats-grid">${metrics.map(([k,n,label,foot])=>`<div class="stat-card" style="--model:${MODEL[k].color};--model-soft:${MODEL[k].soft}"><span class="stat-label">${label}</span><span class="stat-icon">${icon(MODEL[k].icon,17)}</span><strong class="stat-number">${number(n)}</strong><span class="stat-foot"><b>●</b> ${foot}</span></div>`).join('')}</div>`+
 `<div class="two-column"><section class="panel"><div class="panel-head"><h2>当前建模项目</h2><button class="text-button" data-projects>切换项目 ${icon('chevron',12)}</button></div><div class="panel-body"><div class="project-overview"><div class="repo-icon">${icon('git',23)}</div><div><h3>${esc(S.project.name)}</h3><div class="repo-subtitle">${S.project.source_type==='documents'?'文档知识 · 待评审草稿':'Java / Spring'} ${tag(snap.kind==='imported'?'已有建模结果':S.project.source_type==='documents'?'文档提取完成':'静态分析完成','success')} ${tag('待领域评审','purple')}</div></div></div><div class="repo-path" title="${esc(S.project.path)}">${icon('folder',13)}<span class="overflow-clip">${esc(S.project.repo_url||S.project.path)}</span></div><div class="repo-details"><div><small>${S.project.source_type==='documents'?'文档分组':'业务模块'}</small>${Object.keys(d.contexts).length} 组</div><div><small>${S.project.source_type==='documents'?'资料指纹':'源码版本'}</small><span class="mono">${esc(commit)}</span></div><div><small>模型关系</small>${number(d.edges.length)} 条关联</div></div><div class="repo-bottom"><span>${icon('clock',11)} ${snap.kind==='imported'?'导入于':'建模于'} ${time(snap.created_at)}</span><button class="text-button" data-route="exports">版本与产物 ${icon('arrow',12)}</button></div></div></section>
 <section class="panel"><div class="panel-head"><h2>模型质量概览</h2><button class="text-button" data-route="quality">覆盖与质量 ${icon('arrow',12)}</button></div><div class="panel-body"><div class="quality-summary"><svg class="progress-ring" viewBox="0 0 70 70"><circle cx="35" cy="35" r="27" fill="none" stroke="#f0edf6" stroke-width="5"/><circle cx="35" cy="35" r="27" fill="none" stroke="#ae9bca" stroke-width="5" stroke-dasharray="${checks.length?passed/checks.length*169.65:0} 169.65" stroke-linecap="round"/></svg><div><h3>${passed}<span style="font-size:13px;color:#b8afc3"> / ${checks.length}</span></h3><p>模型引用与结构检查通过</p></div></div><div class="quality-meta"><div><strong>${Object.values(d.models['m7-report-model.yaml']?.query_reports||[]).reduce((n,q)=>n+(q.resultColumns||[]).length,0)}</strong><small>查询返回字段</small></div><div><strong>${(d.reviews||[]).filter(r=>r.status==='confirmed').length}</strong><small>已确认语义元素</small></div></div><div class="mini-bars">${Array.from({length:20},()=>'<i></i>').join('')}</div></div></section></div>`+
 `<div class="section-title"><div><h2>七模型语义空间</h2><p>不同视角，共同描述同一份业务知识</p></div><button class="text-button" data-route="models">进入建模工作台 ${icon('arrow',13)}</button></div><div class="model-grid">${Object.entries(MODEL).map(([k,m])=>`<button class="model-card" data-model="${k}" style="--model:${m.color};--model-soft:${m.soft}"><div class="model-icon"><span>${icon(m.icon,16)}</span><span class="model-code">${k}</span></div><h3>${m.name}</h3><strong class="count">${number(counts[k])}<small>个元素</small></strong></button>`).join('')}</div>`+
 `<div class="section-title"><h2>${S.project.source_type==='documents'?'知识文档分组':'业务域导航'} <span style="color:#b9afc5;font-size:10px;font-weight:400;margin-left:9px">${Object.keys(d.contexts).length} 个模块</span></h2><button class="text-button" data-route="models">查看覆盖矩阵 ${icon('arrow',13)}</button></div><div class="domain-list">${Object.entries(d.contexts).slice(0,12).map(([k,v])=>`<button class="domain-chip" data-context="${k}"><i></i>${esc(v)}<span>${nodes().filter(n=>n.context===k&&n.model!=='CTX').length} 个元素</span></button>`).join('')}</div>`;
}

function documentSummary(d){const inv=d.manifest.documentInventory||{},files=inv.files||[];return `<section class="panel document-summary"><div class="panel-head"><h2>${icon('file',17)} 文档知识建模</h2>${tag('候选草稿 · 待领域评审','purple')}</div><div class="panel-body"><div class="document-summary-metrics"><span><b>${files.length}</b> 已读取文档</span><span><b>${(inv.skipped||[]).length}</b> 读取跳过</span><span><b>${Object.values(inv.unsupported||{}).reduce((a,b)=>a+b,0)}</b> 不支持的文件</span></div><p>文档标题和表格是当前建模依据；引用关系不表示调用或执行顺序。M6 保留流程描述，M7 保留查询定义，缺失的字段、权限和分支需领域评审后补齐。</p><details><summary>查看资料范围与建模边界</summary><div class="document-inventory">${files.map(f=>`<div>${icon('file',12)} ${esc(f.path)}</div>`).join('')}${(inv.skipped||[]).map(f=>`<div class="job-error">跳过 ${esc(f.path)}：${esc(f.message)}</div>`).join('')}${Object.entries(inv.unsupported||{}).map(([ext,n])=>`<div>未支持 ${esc(ext)} · ${n} 份</div>`).join('')}</div><ul class="scope-list">${(d.manifest.limitations||[]).map(l=>`<li>${esc(l)}</li>`).join('')}</ul></details></div></section>`}
function qualityNotice(data){const q=data.quality;if(!q)return '';const bad=q.status==='insufficient'||q.status==='blocked';if(data.manifest.ai)return `<div class="notice" style="margin-bottom:20px">${icon('spark',16)}<span>当前为大模型补充草稿 · ${esc(data.manifest.ai.model)}。证据锚点已检查，业务语义待评审。</span><button class="text-button" data-route="ai">查看分析与业务问题</button></div>`;return `<div class="notice ${bad?'quality-notice-critical':''}" style="margin-bottom:20px">${icon('info',16)}<span>${bad?'当前快照覆盖不足或存在校验问题，请先核查后再用于业务编码。':data.manifest.adapter==='document-directory'?'当前为文档候选草稿，文档声明不代表系统已实现；流程与查询契约仍需形式化。':'当前为静态反向建模基线，结构校验通过不代表业务完整或准确。'} · ${q.summary.issues} 项诊断提示</span><button class="text-button" data-route="quality">查看诊断 ${icon('arrow',12)}</button></div>`}
function aiActions(){return `<button class="button primary" data-ai-start>${icon('spark',14)}大模型先分析</button><button class="button" data-route="ai">分析与确认记录</button>`}
function renderAI(){if(!S.project){$('content').innerHTML=empty('请先选择项目','从代码仓库或知识目录建立建模项目后，即可使用模型分析。');return}$('content').innerHTML=heading('AI 分析与业务确认','先由模型核对证据与建模缺口，再将无法确定的问题交给业务人员。')+'<div id="ai-workspace"></div>';mountAIWorkbench($('ai-workspace'),{api,project:S.project,data:S.data,config:S.boot.llm,jobs:S.boot.jobs,start:()=>startAI(),onSource:showSource,onApplied:async()=>{S.snapshot=null;await refreshBootstrap();await loadProjectData();toast('已生成独立的补充草稿快照，原始模型已保留')}})}
async function startAI({jobId,issueId}={}){if(!S.boot.llm?.ready){navigate('settings');toast('请先配置并启用大模型服务');return}try{if(jobId){const job=S.boot.jobs.find(j=>j.id===jobId);if(!job)throw Error('任务已变化，请刷新后重试');if(S.project?.id!==job.project_id)await chooseProject(job.project_id,false)}const fallback=!S.data?S.boot.jobs.find(j=>j.project_id===S.project?.id&&!['queued','running'].includes(j.status)):null;await api(`/projects/${S.project.id}/ai/analyze`,{method:'POST',body:JSON.stringify({jobId:jobId||fallback?.id,snapshotId:!jobId?S.data?.snapshot.id:undefined,issueId})});await refreshBootstrap();navigate('ai');if(S.route==='ai')render();toast('已启动模型分析，可在此查看进度和业务待确认项');schedulePoll()}catch(error){toast(error.message,true)}}
function renderQuality(){if(needData())return;$('content').innerHTML=heading('覆盖与质量','核对源码候选、提取缺口和证据状态，明确模型可用范围。',aiActions()+`<button class="button" data-route="compare">${icon('git',14)}比较快照</button>`)+`<div id="quality-workspace"></div>`;mountQuality($('quality-workspace'),S.data,{onNode:openNode,onSource:showSource});}
function renderCompare(){if(needData())return;$('content').innerHTML=heading('快照差异','将模型内容变化与来源证据变化分开，定位需要复核的业务范围。',`<button class="button" data-route="exports">${icon('clock',14)}快照历史</button>`)+`<div id="compare-workspace"></div>`;mountCompare($('compare-workspace'),{project:S.project,snapshots:S.projectSnapshots||[],api,state:S.compare,onSource:showSource});}

function filterBar(placeholder='搜索名称、标识或类名',extra=''){return `<div class="toolbar"><input class="field-input search-input" id="model-search" placeholder="${placeholder}" value="${esc(S.search)}"><select class="field-input" id="context-filter"><option value="">全部业务域</option>${Object.entries(S.data.contexts).map(([k,v])=>`<option value="${k}" ${S.context===k?'selected':''}>${esc(v)}</option>`).join('')}</select>${extra}<span class="toolbar-note">来源证据可追溯</span></div>`}
function filtered(list){const q=S.search.toLowerCase();return list.filter(n=>(!S.context||n.context===S.context)&&(!q||JSON.stringify([n.label,n.id,n.alias,n.endpoint]).toLowerCase().includes(q)))}
function table(list,kind='models'){const total=list.length,limit=12,max=Math.max(1,Math.ceil(total/limit));S.page=Math.min(max,S.page);const visible=list.slice((S.page-1)*limit,S.page*limit),rv=reviews();return `<div class="table-grid"><table class="data-table"><thead><tr><th>模型元素 / 标识</th><th>模型类型</th><th>业务域</th><th>${kind==='queries'?'参数 / 返回列':'证据'}</th><th>评审状态</th><th></th></tr></thead><tbody>${visible.map(n=>{const r=rv.get(n.id);return `<tr data-node="${esc(n.id)}" tabindex="0"><td><strong>${esc(n.label)}</strong><small>${esc(n.id)}</small></td><td>${modelTag(n.model)}</td><td>${esc(S.data.contexts[n.context]||n.context)}</td><td>${kind==='queries'?`${n.parameters?.length||0} / ${n.resultColumns?.length||0}`:n.evidence?.length?`${n.evidence.length} 处源码`:'关联模型'}</td><td>${tag(r?.status==='confirmed'?'已确认':r?.status==='needs_changes'?'需修订':n.humanEdited?'人工修订':'未评审',r?.status==='confirmed'?'success':r?.status==='needs_changes'?'warning':'neutral')}</td><td class="arrow-cell">${icon('chevron',14)}</td></tr>`}).join('')||`<tr><td colspan="6">${empty('没有匹配的模型','调整业务域或搜索关键词后再试。')}</td></tr>`}</tbody></table></div><div class="pagination"><span>共 ${total} 个元素 · 第 ${S.page} / ${max} 页</span><div class="page-buttons"><button class="button small" data-page="${S.page-1}" ${S.page===1?'disabled':''}>上一页</button><button class="button small" data-page="${S.page+1}" ${S.page===max?'disabled':''}>下一页</button></div></div>`}
function renderModels(){if(needData())return;const counts=modelCounts();$('content').innerHTML=heading('七模型工作台','在统一语义空间中查看、修订与评审模型，每一次理解都保留证据。',`<div class="page-view-switch"><button data-modelview="list" class="${S.modelView==='list'?'active':''}">元素列表</button><button data-modelview="matrix" class="${S.modelView==='matrix'?'active':''}">覆盖矩阵</button></div>`)+`<div class="tabs"><button class="tab ${!S.type?'active':''}" data-type="">全部模型 ${nodes().filter(n=>n.model!=='CTX').length}</button>${Object.entries(MODEL).map(([k,m])=>`<button class="tab ${S.type===k?'active':''}" data-type="${k}">${k} ${m.name} <small>${counts[k]}</small></button>`).join('')}</div><section class="panel">${filterBar()}${S.modelView==='matrix'?matrix():table(filtered(nodes().filter(n=>n.model!=='CTX'&&(!S.type||n.model===S.type))))}</section>`}
function matrix(){return `<div class="table-grid"><table class="data-table matrix-table"><thead><tr><th>业务模块</th>${Object.keys(MODEL).map(k=>`<th>${k}</th>`).join('')}<th>覆盖说明</th></tr></thead><tbody>${Object.entries(S.data.contexts).filter(([k,v])=>(!S.context||k===S.context)&&(!S.search||v.includes(S.search)||k.includes(S.search))).map(([c,label])=>`<tr><td><strong>${esc(label)}</strong><small>${esc(c)}</small></td>${Object.keys(MODEL).map(k=>{const n=nodes().filter(n=>n.context===c&&n.model===k).length;return `<td>${n?`<button class="matrix-number" data-matrix-context="${c}" data-matrix-model="${k}">${n}</button>`:'<span style="color:#d2c7dd">—</span>'}</td>`}).join('')}<td>${tag(c==='installment'?'开发中':c==='web'?'界面与代理':'静态反向模型',c==='installment'?'warning':'neutral')}</td></tr>`).join('')}</tbody></table></div>`}
function renderGraph(){if(needData())return;$('content').innerHTML=heading('探索业务本体图谱','把分散的业务实现连接起来，沿着关系找到定义与证据。',`<div class="page-view-switch"><button data-graph-mode="all" class="${S.graphMode==='all'?'active':''}">全部本体</button><button data-graph-mode="domains" class="${S.graphMode==='domains'?'active':''}">业务域</button><button data-graph-mode="objects" class="${S.graphMode==='objects'?'active':''}">对象关系</button></div>`)+`<section class="panel" style="margin-bottom:15px">${filterBar('在当前项目中搜索',`<select id="graph-model-filter" class="field-input"><option value="">全部模型类型</option>${Object.entries(MODEL).map(([k,m])=>`<option value="${k}" ${S.type===k?'selected':''}>${k} ${m.name}</option>`).join('')}</select>`)}</section><div class="graph-panel" id="graph-container"></div>`;graph=new GraphView($('graph-container'),S.data,{mode:S.graphMode,context:S.context,type:S.type,view:S.graphPrefs,onViewChange:v=>{S.graphPrefs=v},onClear:closeInspector,onSelect:n=>openNode(n),onOpen:n=>{if(n.model==='CTX'){S.context=n.context;S.graphMode='all';render()}else if(n.model==='M6'){S.flowId=n.id;navigate('flows')}}});if(S.search){const matches=filtered(nodes());const n=matches.find(n=>graph.nodes.some(x=>x.id===n.id));if(n)graph.selectById(n.id,true)}}
function renderFlows(){if(needData())return;const flows=nodes().filter(n=>n.model==='M6').sort((a,b)=>(a.modelingLevel==='BUSINESS_LIFECYCLE'?0:1)-(b.modelingLevel==='BUSINESS_LIFECYCLE'?0:1));const visible=flows.filter(n=>(!S.context||n.context===S.context)&&(!S.flowLevel||n.modelingLevel===S.flowLevel)&&(!S.flowSearch||JSON.stringify([n.label,n.id]).toLowerCase().includes(S.flowSearch.toLowerCase())));const active=visible.find(f=>f.id===S.flowId)||visible[0];if(active)S.flowId=active.id;
 $('content').innerHTML=heading('流程模型','从业务生命周期下钻到应用执行，查看分支、异常与跨对象协同。',`<select class="field-input" id="context-filter"><option value="">全部业务域</option>${Object.entries(S.data.contexts).map(([c,v])=>`<option value="${c}" ${c===S.context?'selected':''}>${esc(v)}</option>`).join('')}</select>`)+`<div class="flow-layout"><div class="flow-library"><div class="flow-library-head"><div style="display:flex;justify-content:space-between;color:#9e8cb1;font-size:11px">流程目录 <span>${visible.length} 条</span></div><input id="flow-search" class="field-input" placeholder="搜索流程" value="${esc(S.flowSearch)}"><select id="flow-level" class="field-input"><option value="">全部流程层级</option><option value="BUSINESS_LIFECYCLE" ${S.flowLevel==='BUSINESS_LIFECYCLE'?'selected':''}>业务生命周期</option><option value="DOCUMENT_DRAFT" ${S.flowLevel==='DOCUMENT_DRAFT'?'selected':''}>文档流程草稿</option><option value="APPLICATION_ORCHESTRATION" ${S.flowLevel==='APPLICATION_ORCHESTRATION'?'selected':''}>应用执行流程</option></select></div>${visible.map(f=>`<button class="flow-item ${f.id===active?.id?'active':''}" data-flow="${esc(f.id)}"><span class="flow-type">${f.modelingLevel==='DOCUMENT_DRAFT'?'◇ 文档流程草稿':f.modelingLevel==='BUSINESS_LIFECYCLE'?'◇ 业务生命周期':'⌁ 应用执行流程'} · ${esc(S.data.contexts[f.context])}</span><strong>${esc(f.label)}</strong><small>${f.activities?.length||0} 个活动 · ${f.activities?.filter(a=>a.activityType==='GATEWAY').length||0} 个网关</small></button>`).join('')||empty('暂无匹配流程','该范围没有可识别的执行流程。')}</div><div class="graph-panel" id="flow-graph"></div></div>`;
 if(active?.formalizationStatus==='DOCUMENT_NARRATIVE_ONLY'){$('flow-graph').innerHTML=`<div class="document-flow-draft">${tag('文档流程 · 尚待形式化','purple')}<h2>${esc(active.label)}</h2><p>${esc(active.description)}</p><p>当前保留原始业务描述，尚未生成可执行活动及分支。请核验来源后补充流程细节。</p><button class="button" data-node="${esc(active.id)}">查看定义与文档证据</button></div>`;return;}graph=new GraphView($('flow-graph'),S.data,{mode:'flow',flow:active,onSelect:a=>openNode({...a,flow:active}),onOpen:a=>{if(a.subFlowRef){S.flowId=a.subFlowRef;S.context='';S.flowLevel='';S.flowSearch='';closeInspector();render()}}});if(active){const toolbar=$('flow-graph').querySelector('.graph-toolbar');toolbar.insertAdjacentHTML('beforeend',`<button class="button small" data-node="${esc(active.id)}">流程详情 ${icon('chevron',12)}</button>`)}}
function renderQueries(){if(needData())return;const list=filtered(nodes().filter(n=>n.model==='M7'));$('content').innerHTML=heading('查询与报表','从输入条件到返回结构，追溯每一份业务查询的数据语义。',`<button class="button" data-route="exports">${icon('download',14)}导出查询模型</button>`)+`<div class="notice">${icon('info',15)}<span>直接 DTO 映射、已核验统计表达式与待评审候选分别标注。查询契约覆盖不等于所有业务公式均已证明。</span></div><section class="panel">${filterBar('搜索查询、报表或接口')}${table(list,'queries')}</section>`}
function renderReview(){if(needData())return;const checks=S.data.manifest.validation||[],rv=reviews(),confirmed=[...rv.values()].filter(r=>r.status==='confirmed').length,needs=[...rv.values()].filter(r=>r.status==='needs_changes').length;const list=filtered(nodes().filter(n=>n.model!=='CTX'&&rv.get(n.id)?.status!=='confirmed'));$('content').innerHTML=heading('校验与评审','让结构检查与业务判断各司其职，将每一次确认沉淀为可信语义。',aiActions())+`<div class="review-overview"><div class="review-metric"><strong>${checks.filter(c=>c.passed).length} / ${checks.length}</strong><span>结构与引用检查通过</span></div><div class="review-metric"><strong>${confirmed}</strong><span>人工确认的语义元素</span></div><div class="review-metric"><strong>${needs}</strong><span>标记为需要修订</span></div></div><div class="tabs"><button class="tab ${S.reviewTab==='checks'?'active':''}" data-reviewtab="checks">结构校验</button><button class="tab ${S.reviewTab==='pending'?'active':''}" data-reviewtab="pending">语义待办 ${nodes().filter(n=>n.model!=='CTX').length-confirmed}</button><button class="tab ${S.reviewTab==='lineage'?'active':''}" data-reviewtab="lineage">血缘质量</button></div>`+(S.reviewTab==='checks'?`<section class="panel"><div class="panel-head"><h2>模型结构校验结果</h2>${tag('不替代业务验收','purple')}</div><div class="check-list">${checks.map(c=>`<div class="check-row"><span class="check-icon" style="${!c.passed?'background:#fff0ee;color:#bd8181':''}">${icon(c.passed?'check':'close',12)}</span><span>${esc(checkName(c.check))}</span><small>${c.count} 项引用</small></div>`).join('')}</div></section>`:S.reviewTab==='pending'?`<section class="panel">${filterBar('搜索待评审模型')}${table(list)}</section>`:lineagePanel());}
function checkName(s){const known={'M2 USER_ACTION → MU action coverage':'用户触发行为具有可追溯的界面入口','MU → M2 behavior existence':'界面引用的业务行为均存在','M7 ↔ M2 one-to-one':'查询模型与业务行为双向一对一','M6 behavior references':'流程中的行为引用完整','M1 reference targets':'对象之间的引用目标存在','M2 syncTriggers references':'同步联动规则与行为引用有效','Graph references':'图谱关系两端均存在','Unique node identifiers':'本体元素标识唯一','M6 one START and valid END activities':'每条流程具有唯一开始和合法结束','M6 activity, behavior, subflow and rule references':'流程活动、子流程及规则引用有效','M6 all activities reachable':'所有流程活动从开始节点可达','M6 all activity paths can reach an END':'所有活动存在到达结束的路径','M6 gateways have conditional/default branches':'网关条件与默认分支合法','M6 role references':'人工任务角色引用合法','M6 business object references are roots':'流程对象均引用有效聚合根','M6 SUB_FLOW_CALL graph is acyclic':'子流程调用不存在递归环','M7 unique QUERY behavior and bidirectional binding':'查询行为唯一且双向绑定','M7 valid root sources and exactly one primary':'查询具有唯一主来源及有效业务对象','M7 source aliases and join references':'查询来源别名与关联引用有效','M7 parameter and response contract populated':'查询参数和返回结构已恢复','M7 contains no role/rule/flow permission references':'查询模型遵循跨模型引用边界','M7 proven DTO mappings resolve to M1 fields':'已证明的 DTO 映射可解析到对象字段','M7 REPORT objects include reportOptions':'固定报表具有展示定义','Payment SETTLED idempotence and ACCEPTED guard preserved':'支付幂等与清算前置条件保留','Report generation retains failure-write and rethrow':'报表生成保留失败状态与异常回传','Transaction report distinguishes page and global sums':'交易报表区分页合计与全量合计','POST report generation remains COMMAND':'写入报表运行记录的操作仍归类为命令'};return known[s]||s}
function lineagePanel(){const columns=nodes().filter(n=>n.model==='M7').flatMap(n=>n.resultColumns||[]),counts=columns.reduce((o,c)=>(o[c.mappingStatus]=(o[c.mappingStatus]||0)+1,o),{});return `<section class="panel"><div class="panel-head"><h2>查询返回字段的证据状态</h2>${tag(`${columns.length} 个字段`,'purple')}</div><div class="panel-body"><div class="notice">${icon('info',16)}<span>只将存在明确构造参数或计算公式的映射标记为已核验。同名候选和仅恢复契约的字段单独保留，避免把猜测当成业务事实。</span></div>${Object.entries({DTO_CONSTRUCTOR_VERIFIED:'DTO 构造映射已核对',SOURCE_VERIFIED:'统计表达式已核验',NAME_MATCH_REVIEW:'同名候选 · 需要评审',DTO_CONTRACT_ONLY:'返回结构已恢复 · 血缘待补充'}).map(([k,v])=>`<div class="setting-row"><span>${v}</span><strong>${counts[k]||0}</strong></div>`).join('')}</div></section>`}
function renderJobs(){const list=S.boot.jobs;const labels={completed:['已完成','success'],running:['分析中','purple'],queued:['排队中','neutral'],failed:['失败','error'],cancelled:['已取消','neutral']};$('content').innerHTML=heading('建模任务','每一次分析都有过程、有结果，也有清晰的失败原因。',`<button class="button primary" data-new>${icon('plus',15)}新建建模任务</button>`)+(S.boot.pendingCleanup?.length?`<div class="notice" style="margin-bottom:18px"><span>有 ${S.boot.pendingCleanup.length} 项文件清理尚未完成。</span><button class="button small" data-cleanup-jobs>重试文件清理</button></div>`:'')+(list.length?list.map(j=>`<section class="job-card"><div class="job-title"><span class="repo-icon" style="width:33px;height:33px">${icon('jobs',17)}</span><strong>${esc(j.project_name)}</strong>${tag(...(labels[j.status]||[j.status,'neutral']))}</div><div class="job-meta">${esc(j.id)} · ${time(j.started_at||j.created_at)} ${j.finished_at?'→ '+time(j.finished_at):''}</div><div style="display:flex;justify-content:space-between;color:#a28bb2;font-size:11px"><span>${esc(j.stage)}</span><span>${j.progress}%</span></div><div class="progress-track"><div class="progress-fill" style="width:${j.progress}%"></div></div><div class="job-stages">${['准备资料','只读快照','七模型生成','校验与溯源','保存结果'].map((s,i)=>`<span class="${j.progress>=(i+1)*20?'done':''}">${s}</span>`).join('')}</div>${j.error?`<p class="job-error">${esc(j.error)}</p>${/未发现 src\/main\/java/.test(j.error)?`<div class="notice"><span>如果输入是业务文档，可直接改用知识解析器重试。</span><button class="button small" data-doc-retry="${j.project_id}">按知识目录重试</button></div>`:''}`:''}<details class="job-events" ${['running','failed'].includes(j.status)?'open':''}><summary style="font-size:10px;color:#b6a1c3;cursor:pointer">查看分析日志 · ${j.events.length} 条</summary>${j.events.map(e=>`<div class="job-event"><time>${time(e.time)}</time><span>${esc(e.message)}</span></div>`).join('')}</details><div style="display:flex;justify-content:flex-end;margin-top:15px;gap:8px">${!['queued','running'].includes(j.status)?`<button class="button small" data-ai-job="${j.id}">${icon('spark',12)}${j.status==='failed'?'大模型辅助解析':'大模型分析不确定项'}</button>`:''}<button class="button small danger" data-delete-job="${j.id}" ${j.status==='running'?'disabled title="请先取消任务，待进程停止后再删除"':''}>删除任务</button>${['running','queued'].includes(j.status)?`<button class="button small danger" data-cancel="${j.id}">${icon('stop',12)}取消任务</button>`:j.status==='completed'?`<button class="button small" data-job-quality="${j.id}">覆盖诊断</button><button class="button small" data-job-project="${j.project_id}">查看建模结果 ${icon('arrow',12)}</button>`:`<button class="button small" data-retry="${j.project_id}">重新分析</button>`}</div></section>`).join(''):empty('还没有运行任务','可以重新分析当前项目；独立导入的模型快照不受任务删除影响。',S.project?'<button class="button primary" data-reanalyze>重新分析当前项目</button>':'<button class="button primary" data-new>接入建模资料</button>'));}
function exportURL(format,file){return `/api/projects/${S.project.id}/export?format=${format}&snapshot=${encodeURIComponent(S.data.snapshot.id)}${file?'&file='+encodeURIComponent(file):''}`}
function renderExports(){if(needData())return;const list=S.projectSnapshots||[],snapshot=S.data.snapshot;$('content').innerHTML=heading('版本与导出','保留每一次建模结果，将语义资产带到评审、开发与后续分析中。',`<button class="button" data-route="compare">${icon('git',14)}比较快照</button><select class="field-input snapshot-select" id="snapshot-select"><option value="">当前最新快照</option>${list.map(s=>`<option value="${s.id}" ${S.snapshot===s.id?'selected':''}>${time(s.created_at)} · ${s.kind==='imported'?'导入基线':'分析快照'}</option>`).join('')}</select>`)+`<div class="export-grid">${[['json','layers','完整模型数据','七模型、图谱关系、来源证据和评审记录，便于继续加工与系统集成。','JSON'],['html','layout','离线建模报告','可离线搜索模型目录、查看属性和证据，方便保存与团队评审。','HTML'],['yaml','file','七模型文件','按模型分别导出 YAML 1.2 文件，保留可追溯的业务语义与待评审状态。','YAML']].map(([format,ic,name,desc,ext])=>`<div class="export-card"><div class="model-icon">${icon(ic,23)}</div><h3>${name}</h3><p>${desc}</p>${format==='yaml'?'<button class="button" data-scroll-yaml>选择模型文件</button>':`<a class="button" href="${exportURL(format)}" download>${icon('download',14)}导出 ${ext}</a>`}</div>`).join('')}</div><section class="panel" id="yaml-files"><div class="panel-head"><h2>七模型产物</h2>${tag('YAML 1.2 · JSON 序列化','purple')}</div><div class="panel-body"><div class="card-action-list">${Object.entries(MODEL).map(([k,m])=>{const file=Object.keys(S.data.models).find(f=>f.startsWith(k==='MU'?'mu-':k.toLowerCase()+'-'));return file?`<a class="button" href="${exportURL('yaml',file)}" download>${icon('file',13)}${k} ${m.name} ${icon('download',12)}</a>`:''}).join('')}</div></div></section><section class="panel" style="margin-top:22px"><div class="panel-head"><h2>模型快照历史</h2><small style="color:#b8a4c6">评审与修订按快照独立保存</small></div><div class="table-grid"><table class="data-table"><thead><tr><th>生成时间</th><th>来源</th><th>本体元素</th><th>关联关系</th><th>状态</th><th></th></tr></thead><tbody>${list.map(s=>`<tr data-snapshot="${s.id}"><td><strong>${time(s.created_at)}</strong><small>${esc(s.id)}</small></td><td>${s.kind==='ai_enriched'?'大模型补充草稿':s.kind==='imported'?'已有结果导入':S.project.source_type==='documents'?'知识文档解析':'源码分析'}</td><td>${s.summary.nodes}</td><td>${s.summary.edges}</td><td>${tag(s.id===snapshot.id?'正在查看':'历史快照',s.id===snapshot.id?'purple':'neutral')}</td><td>${icon('chevron',14)}</td></tr>`).join('')}</tbody></table></div></section>`}
function renderSettings(){$('content').innerHTML=heading('能力与设置','轻量技术原型，清晰的能力范围，可追溯的建模结果。')+`<section class="panel" id="llm-settings" style="margin-bottom:22px"></section><div class="settings-grid"><section class="panel"><div class="panel-head"><h2>分析能力</h2>${tag('本地运行','success')}</div><div class="panel-body">${[['建模输入','Java / Spring · 文档知识目录'],['对象识别','JPA 实体、领域对象与 record'],['行为识别','Spring REST → 应用服务'],['流程恢复','条件分支、循环、异常与子流程'],['查询契约','参数、DTO 返回结构与映射'],['模型框架','七模型 v9']].map(([a,b])=>`<div class="setting-row"><span>${a}</span><span>${b}</span></div>`).join('')}</div></section><section class="panel"><div class="panel-head"><h2>All-in-one 运行环境</h2>${tag('技术原型','purple')}</div><div class="panel-body">${[['服务','Node.js 原生 HTTP'],['存储','SQLite · 本机文件'],['分析器','Python 标准库 · 文档候选提取'],['界面','原生模块 · 无构建步骤'],['证据助手','本地语义检索 · SSE'],['配置方式','环境变量 / 启动参数']].map(([a,b])=>`<div class="setting-row"><span>${a}</span><span>${b}</span></div>`).join('')}</div></section></div><section class="panel" style="margin-top:22px"><div class="panel-head"><h2>能力边界</h2><button class="text-button" id="settings-guide">查看完整说明 ${icon('external',12)}</button></div><div class="panel-body"><ul class="scope-list"><li>本地代码、HTTPS Git 仓库及知识文档目录均可接入。远程克隆不支持交互式登录，私有仓库可先在本机克隆后接入。</li><li>只读取分析所需的源码和配置，不执行目标仓库的构建命令、安装脚本或工作区钩子。</li><li>文档支持 Markdown / TXT / HTML / DOCX，最多500份 / 20MB；PDF和扫描件暂不支持。源码输入限 6000 个分析文件 / 60MB。其他语言会明确提示当前不支持深度建模。</li><li>结构校验不替代领域评审。未确认的角色、血缘和规则不会补造为已实现能力。</li><li>证据助手默认使用本地检索；配置并启用大模型后，可基于模型证据进行辅助问答。</li></ul></div></section>`;mountLLMSettings($('llm-settings'),{api,onSaved:async()=>{await refreshBootstrap()}})}
function bindContent(){
 const search=$('model-search');if(search)search.oninput=e=>{const pos=e.target.selectionStart;S.search=e.target.value;S.page=1;render();const n=$('model-search');n?.focus();n?.setSelectionRange(pos,pos)};
 const c=$('context-filter');if(c)c.onchange=e=>{S.context=e.target.value;S.page=1;render()};
 const g=$('graph-model-filter');if(g)g.onchange=e=>{S.type=e.target.value;render()};
 const fs=$('flow-search');if(fs)fs.oninput=e=>{const pos=e.target.selectionStart;S.flowSearch=e.target.value;render();$('flow-search')?.focus();$('flow-search')?.setSelectionRange(pos,pos)};
 const fl=$('flow-level');if(fl)fl.onchange=e=>{S.flowLevel=e.target.value;render()};
 const sn=$('snapshot-select');if(sn)sn.onchange=async e=>{S.snapshot=e.target.value||null;await loadProjectData();render()};
 $('settings-guide')?.addEventListener('click',guide);
}
